/**
 * 恢复邮件页 — 弃单挽回邮件的语气模板与可选 AI 起草
 * 多语言：文案来自 i18n/dictionaries/aiEngine.js
 * @author 恒哥
 */
import React from 'react';
import Layout from '../../components/Layout';
import SEO from '../../components/SEO';
import ProductCardGallery from '../../components/ProductCardGallery';
import FreeInstallCta from '../../components/FreeInstallCta';
import { usePageI18n } from '../../i18n';
import aiCopy from '../../i18n/dictionaries/aiEngine';
import { CART_PRODUCT_CARDS } from '../../constants/brand';
import './ai-email-engine.css';

export default function AiEmailEnginePage({ pageContext }) {
  const { locale } = usePageI18n(pageContext);
  const c = aiCopy[locale] || aiCopy.en;
  // 本页只展示「收件箱效果」与「发送时序」两张卡。
  // 🔴 这依赖 CART_PRODUCT_CARDS 的 `id` 字段——它此前缺失，导致这里恒为空数组
  //    （画廊不渲染任何内容）。已在 brand.js 的 cartCard() 补上 id 并逐张显式命名。
  const emailCards = CART_PRODUCT_CARDS.filter((card) => card.id === 'email' || card.id === 'timing');

  return (
    <Layout locale={pageContext?.locale}>
      <SEO
        title={c.metaTitle}
        description={c.metaDesc}
        pathname="/features/ai-email-engine"
        hrefLang={locale}
      />
      <div className="ai-page">
        <div className="page-header ai-page-header">
          <span className="ai-page-eyebrow">{c.eyebrow}</span>
          <h1>{c.h1}</h1>
          <p>{c.lead}</p>
        </div>

        <p className="ai-tier-note">
          {c.tierNotePre} <strong>Growth</strong> {c.tierNoteMid} <strong>Pro</strong> {c.tierNotePost}
        </p>

        <section className="ai-section">
          <h2>{c.flowTitle}</h2>
          <ol className="ai-flow">
            {c.flow.map((step) => (
              <li key={step} dangerouslySetInnerHTML={{ __html: step }} />
            ))}
          </ol>
        </section>

        <section className="ai-section">
          <h2>{c.toneTitle}</h2>
          <p className="ai-lead">{c.toneLead}</p>
          <div className="ai-tone-grid">
            {c.samples.map((s) => (
              <div key={s.tone} className="ai-tone-card">
                <div className="ai-tone-meta">
                  <span className="ai-tone-tag">{c.toneTag}</span>
                  <span>{c.toneLabel.replace('{tone}', s.tone)}</span>
                </div>
                <p className="ai-tone-subject">{c.subjectLabel.replace('{subject}', s.subject)}</p>
                <p className="ai-tone-body">{s.body}</p>
              </div>
            ))}
          </div>
        </section>

        <section className="ai-section">
          <h2>{c.seeTitle}</h2>
          <ProductCardGallery cards={emailCards} initialIndex={0} autoPlay intervalMs={4000} />
        </section>

        <section className="ai-section">
          <h2>{c.detailTitle}</h2>
          <div className="ai-detail-grid">
            {c.details.map((d) => (
              <div key={d.title} className="ai-detail-card">
                <h3>{d.title}</h3>
                <p>{d.text}</p>
              </div>
            ))}
          </div>
        </section>

        <div className="ai-cta ai-cta-free">
          <FreeInstallCta variant="card" title={c.ctaTitle} />
        </div>
      </div>
    </Layout>
  );
}